let state = null;

const EVENTS = ["mousemove", "keydown", "click", "scroll", "touchstart"];

function handleActivity() {
    if (!state) return;

    clearTimeout(state.timerId);

    if (state.isIdle) {
        state.isIdle = false;
        state.dotNetRef.invokeMethodAsync("OnActiveCallback");
    }

    state.timerId = setTimeout(() => {
        if (!state) return;
        state.isIdle = true;
        state.dotNetRef.invokeMethodAsync("OnIdleCallback");
    }, state.timeoutMs);
}

export function initialize(element, dotNetRef, timeoutSeconds) {
    state = {
        element,
        dotNetRef,
        timeoutMs: timeoutSeconds * 1000,
        isIdle: false,
        timerId: null,
        handler: handleActivity
    };

    for (const evt of EVENTS) {
        document.addEventListener(evt, state.handler, { passive: true });
    }

    // Start the initial idle timer
    state.timerId = setTimeout(() => {
        if (!state) return;
        state.isIdle = true;
        state.dotNetRef.invokeMethodAsync("OnIdleCallback");
    }, state.timeoutMs);
}

export function dispose() {
    if (!state) return;

    clearTimeout(state.timerId);

    for (const evt of EVENTS) {
        document.removeEventListener(evt, state.handler);
    }

    state = null;
}

